package server_test

import (
	"embed"
	"os"
	"path/filepath"
	"testing"

	"github.com/pocketbase/pocketbase/core"
	"github.com/pocketbase/pocketbase/tools/archive"

	_ "github.com/piggybudget/piggybudget/apps/server/pb_migrations"
)

// The archive was generated by the Piggybudget-era source at this immutable
// Git commit, before transaction attachment and asset group migrations.
const historicalPiggybudgetSourceCommit = "eb40d6220d3de11d6cc36ec4456dce80be160cb3"

//go:embed testdata/piggybudget-eb40d62-populated.zip
var historicalPiggybudgetFixture embed.FS

func TestHistoricalSourceBackupUpgradePreservesFinanceRecords(t *testing.T) {
	fixture, err := historicalPiggybudgetFixture.ReadFile("testdata/piggybudget-eb40d62-populated.zip")
	if err != nil {
		t.Fatal(err)
	}

	// Restore only into a fresh disposable directory. The checked-in archive
	// contains synthetic records and is not copied from a user's pb_data.
	restoreDir := t.TempDir()
	archivePath := filepath.Join(t.TempDir(), "piggybudget-historical.zip")
	if err := os.WriteFile(archivePath, fixture, 0o600); err != nil {
		t.Fatal(err)
	}
	if err := archive.Extract(archivePath, restoreDir); err != nil {
		t.Fatalf("restore historical-source backup: %v", err)
	}
	if _, err := os.Stat(filepath.Join(restoreDir, "data.db")); err != nil {
		t.Fatalf("restored historical backup has no data.db: %v", err)
	}

	// Open the database with the current PocketBase runtime before running its
	// app migrations. The two newer collections must not exist in this old DB.
	currentApp := core.NewBaseApp(core.BaseAppConfig{DataDir: restoreDir})
	if err := currentApp.Bootstrap(); err != nil {
		t.Fatalf("boot current runtime from historical Piggybudget backup (%s): %v", historicalPiggybudgetSourceCommit, err)
	}
	defer func() { _ = currentApp.ResetBootstrapState() }()
	for _, name := range []string{"transaction_attachments", "asset_groups", "asset_positions"} {
		if _, err := currentApp.FindCollectionByNameOrId(name); err == nil {
			t.Fatalf("historical fixture unexpectedly already contains post-%s collection %q", historicalPiggybudgetSourceCommit, name)
		}
	}

	assertHistoricalFinanceRecord(t, currentApp, "users", "histuser0000001", map[string]any{
		"email": "historical-piggy@example.invalid",
	})
	assertHistoricalFinanceRecord(t, currentApp, "accounts", "histacct0000001", map[string]any{
		"owner": "histuser0000001", "name": "Historical checking", "currency": "EUR", "opening_balance": float64(125.5),
	})
	assertHistoricalFinanceRecord(t, currentApp, "transactions", "histtxn00000001", map[string]any{
		"owner": "histuser0000001", "account": "histacct0000001", "amount": float64(-18.75),
		"payee": "Historical market", "description": "Synthetic historical transaction", "category": "Groceries",
	})
	assertHistoricalFinanceRecord(t, currentApp, "assets", "histasset000001", map[string]any{
		"owner": "histuser0000001", "name": "Historical index fund", "type": "investment", "currency": "EUR",
	})

	// Apply the current migrations twice to verify both the schema upgrade and
	// migration idempotency without recreating the historical database.
	for range 2 {
		if err := currentApp.RunAppMigrations(); err != nil {
			t.Fatalf("run current finance migrations: %v", err)
		}
	}
	for _, name := range []string{"transaction_attachments", "asset_groups", "asset_positions"} {
		if _, err := currentApp.FindCollectionByNameOrId(name); err != nil {
			t.Errorf("current migration did not add %s: %v", name, err)
		}
	}
	assets, err := currentApp.FindCollectionByNameOrId("assets")
	if err != nil {
		t.Fatal(err)
	}
	if assets.Fields.GetByName("asset_group") == nil {
		t.Error("current migration did not add assets.asset_group")
	}

	assertHistoricalFinanceRecord(t, currentApp, "users", "histuser0000001", map[string]any{
		"email": "historical-piggy@example.invalid",
	})
	assertHistoricalFinanceRecord(t, currentApp, "accounts", "histacct0000001", map[string]any{
		"owner": "histuser0000001", "name": "Historical checking", "currency": "EUR", "opening_balance": float64(125.5),
	})
	assertHistoricalFinanceRecord(t, currentApp, "transactions", "histtxn00000001", map[string]any{
		"owner": "histuser0000001", "account": "histacct0000001", "amount": float64(-18.75),
		"payee": "Historical market", "description": "Synthetic historical transaction", "category": "Groceries",
	})
	assertHistoricalFinanceRecord(t, currentApp, "assets", "histasset000001", map[string]any{
		"owner": "histuser0000001", "name": "Historical index fund", "type": "investment", "currency": "EUR",
	})
}

func assertHistoricalFinanceRecord(t *testing.T, testApp core.App, collectionName, recordID string, fields map[string]any) {
	t.Helper()
	record, err := testApp.FindRecordById(collectionName, recordID)
	if err != nil {
		t.Fatalf("find historical %s record %s: %v", collectionName, recordID, err)
	}
	if record.Id != recordID {
		t.Fatalf("historical %s record ID changed: got %q, want %q", collectionName, record.Id, recordID)
	}
	for field, want := range fields {
		if got := record.Get(field); got != want {
			t.Errorf("historical %s.%s = %#v, want %#v", collectionName, field, got, want)
		}
	}
}
